  if (spec2.maxResponseBytes !== void 0) bounds.push(`response up to ${kibibytes(spec2.maxResponseBytes)}`);
  const lines = [`#### \`${spec2.method}\` \u2014 ${spec2.effect} \xB7 ${status}`, "", spec2.description, "", `Parameters: ${spec2.doc.params}`, "", `Result: ${spec2.doc.result}`];
  if (spec2.doc.notes) lines.push("", spec2.doc.notes);
